            ks::SceneManager::timeskip();
            ScriptA3Shizune::a3_shizune_confrontation(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA3Shizune::a3_shizune_the_anchor(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA3Shizune::a3_shizune_roadmap(); // INLINE CALL
